void main() {
    vec4 ks = vec4(0.3, 0.3, 0.3, 0.0); // specular color
    vec4 kd = vec4(0.6, 0.6, 0.3, 0.0); // diffuse color
    vec4 ka = 0.1 * kd; // ambient color
    float diff = max(dot(vertNormal, lightDir), 0.0);

    /// Reflection is based on the incident direction which means a vector from the light source
    /// not the direction to the light source
    vec3 reflection = normalize(reflect(-lightDir, vertNormal));
    float spec = max(dot(eyeDir, reflection), 0.0);
    spec = pow(spec,14.0); // using a shininess constant of 14
    fragColor =  ka + (diff * kd) + (spec * ks); // final color is the sum of ambient, diffuse, and specular
}

