static Vec4 perspectiveDivide(const Vec4& v) {
  if (fabs(v.w) < VERY_SMALL) {
    throw errorMsg.append(": Divide by nearly zero! ");
  }
  return Vec4(v.x / v.w, v.y / v.w, v.z / v.w, 1.0f);
}

